#!/usr/bin/env python3
"""
Round 109b (culprits), 28 September 2026. Needs round 108b.

Shapes raised, alerts coloured by grade, a colour wheel for the layer
colours, the Atlas cities opened in the corner panel only.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = "## Round 109b (28 September)\n\nNeeds round 108b. No tiles patch.\n\n- Of the insentient: heading without quotation marks.\n- The Raise where the points crowd chip is gone. With Raise figures as heights on,\n  riseRow() raises every row: pictures by coverage (rasterRiseSet), points, areas\n  and lines by count/coverage on a 0.25 degree grid (pointReliefSet, shapeCover),\n  read bilinearly; no tint layer, only height and shading. Tile-read rows are\n  recounted on moveend while they hold the ground.\n- Alert rows (gfw, gfw_dist, gfw_dist_year): recolorAlerts gives GFW's three\n  confidence pinks (gfw-tile-cache alerts.py) three steps, ALERT_TONES; keepColour;\n  key under the row.\n- Layer colours: a colour wheel (THEME_CUSTOM, customTheme, themeWheelWire) with\n  a brightness slider and As drawn / Suit basemap buttons; theme 'custom'.\n- Atlas cities: a click opens only #atlas-city (no popup). #atlas-panel[hidden]\n  and #atlas-city[hidden] now display:none (their inline display:flex had kept\n  them showing). ac-grow button top left; atlasCityKey shows the conflicts-map\n  key from atlas/legends.json, labelled as such.\n- test.mjs: appVersion(html) >= N replaces the per-round version regexes.\n- Script version app.js?v=1000.\n\n"
HEAD = "## Round 109b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round109b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 108b" not in text:
        sys.exit("round109b: round 108b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round109b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round109b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round109b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 108b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
